    }
    final name = json['name'];
    if (name is! String) {
      throw const FormatException('Invalid ProfileSummaryDto.name');
    }
    if (!json.containsKey('age')) {
      throw const FormatException('Missing ProfileSummaryDto.age');
    }
    final age = json['age'];
    if (age is! num) {
      throw const FormatException('Invalid ProfileSummaryDto.age');
    }
    if (!json.containsKey('gender')) {
      throw const FormatException('Missing ProfileSummaryDto.gender');
    }
    final gender = json['gender'];
    if (gender is! String) {
      throw const FormatException('Invalid ProfileSummaryDto.gender');
    }
    if (!const [
      "man",
      "woman",
      "another_identity",
      "prefer_not_to_say",
    ].contains(gender)) {
      throw const FormatException('Unsupported gender');
    }
    if (!json.containsKey('bio')) {
      throw const FormatException('Missing ProfileSummaryDto.bio');
    }
    final bio = json['bio'];
    if (bio is! String) {
      throw const FormatException('Invalid ProfileSummaryDto.bio');
    }
    if (!json.containsKey('visibility')) {
      throw const FormatException('Missing ProfileSummaryDto.visibility');
    }
    final visibility = json['visibility'];
    if (visibility is! String) {
      throw const FormatException('Invalid ProfileSummaryDto.visibility');
    }
    if (!const ["private", "public"].contains(visibility)) {
      throw const FormatException('Unsupported visibility');
    }
    if (!json.containsKey('verificationStatus')) {
      throw const FormatException(
        'Missing ProfileSummaryDto.verificationStatus',
      );
    }
    final verificationStatus = json['verificationStatus'];
    if (verificationStatus is! String) {
      throw const FormatException(
        'Invalid ProfileSummaryDto.verificationStatus',
      );
    }
    if (!const [
      "none",
      "pending",
      "approved",
      "declined",
    ].contains(verificationStatus)) {
      throw const FormatException('Unsupported verificationStatus');
    }
    if (!json.containsKey('photoState')) {
      throw const FormatException('Missing ProfileSummaryDto.photoState');
    }
    final photoState = json['photoState'];
    if (photoState is! String) {
      throw const FormatException('Invalid ProfileSummaryDto.photoState');
    }
    if (!const ["unavailable"].contains(photoState)) {
      throw const FormatException('Unsupported photoState');
    }
    return ProfileSummaryDto(
      userId: userId,
      username: username,
      name: name,
      age: age,
      gender: gender,
      bio: bio,
      visibility: visibility,
      verificationStatus: verificationStatus,
      photoState: photoState,
    );
  }
  Map<String, dynamic> toJson() => {
    'userId': userId,
    'username': username,
    'name': name,
    'age': age,
    'gender': gender,
    'bio': bio,
    'visibility': visibility,
    'verificationStatus': verificationStatus,
    'photoState': photoState,
  };
}

final class VerificationDto {
  const VerificationDto({
    required this.status,
    required this.offerSeen,
    required this.uploadsAvailable,
    required this.reason,
  });
  final String status;
  final bool offerSeen;
  final bool uploadsAvailable;
  final String? reason;
  factory VerificationDto.fromJson(Map<String, dynamic> json) {
    if (!json.containsKey('status')) {
      throw const FormatException('Missing VerificationDto.status');
    }
    final status = json['status'];
    if (status is! String) {
      throw const FormatException('Invalid VerificationDto.status');
    }
    if (!const ["none", "pending", "approved", "declined"].contains(status)) {
      throw const FormatException('Unsupported status');
    }
    if (!json.containsKey('offerSeen')) {
      throw const FormatException('Missing VerificationDto.offerSeen');
    }
    final offerSeen = json['offerSeen'];
    if (offerSeen is! bool) {
      throw const FormatException('Invalid VerificationDto.offerSeen');
    }
    if (!json.containsKey('uploadsAvailable')) {
      throw const FormatException('Missing VerificationDto.uploadsAvailable');
    }
    final uploadsAvailable = json['uploadsAvailable'];
    if (uploadsAvailable is! bool) {
      throw const FormatException('Invalid VerificationDto.uploadsAvailable');
    }
    if (!json.containsKey('reason')) {
      throw const FormatException('Missing VerificationDto.reason');
    }
    final reason = json['reason'];
    if (reason != null && reason is! String) {
      throw const FormatException('Invalid VerificationDto.reason');
    }
    return VerificationDto(
      status: status,
      offerSeen: offerSeen,
      uploadsAvailable: uploadsAvailable,
      reason: reason,
    );
  }
  Map<String, dynamic> toJson() => {
    'status': status,
    'offerSeen': offerSeen,
    'uploadsAvailable': uploadsAvailable,
    'reason': reason,
  };
}

final class VerificationInput {
