    if (frontAssetId is! String) {
      throw const FormatException('Invalid VerificationInput.frontAssetId');
    }
    final backAssetId = json['backAssetId'];
    if (backAssetId != null && backAssetId is! String) {
      throw const FormatException('Invalid VerificationInput.backAssetId');
    }
    if (!json.containsKey('consent')) {
      throw const FormatException('Missing VerificationInput.consent');
    }
